const course: DeepCourse = {"slug":"applications-that-get-replies","title":"Applications That Get Replies.","premium":false,"previewCount":3,"chunks":[{"kind":"html","value":"<section class=\"px-5 pt-28 md:px-8 md:pt-40\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Writing · free</p><h1 class=\"display-lg mt-4\">Applications That Get Replies<span class=\"dot\" aria-hidden=\"true\">.</span></h1><p class=\"lede mt-5 max-w-xl\">Stop sending resumes into the void. Write the four-paragraph application that makes one specific person reply.</p><div class=\"mt-8\"><div class=\"flex flex-wrap items-center gap-2.5\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free course</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">8 modules</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">3h 44m of reading and doing</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">8 portfolio pieces</span></div><p class=\"mt-4 mb-2 text-[0.8125rem] text-muted\">Course content is based on active job listings and industry hiring patterns. These are practical guides, not formal certifications.</p></div></div></section><nav aria-label=\"Course sections\" class=\"sticky top-16 z-20 border-b border-line bg-paper/90 backdrop-blur-md\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-6xl\"><ul class=\"-mx-1 flex gap-1 overflow-x-auto py-2.5 [scrollbar-width:none] [&amp;::-webkit-scrollbar]:hidden\"><li><a href=\"#the-job\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">The job</a></li><li><a href=\"#tools\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Tools</a></li><li><a href=\"#modules\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Modules</a></li><li><a href=\"#rates\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Rates</a></li><li><a href=\"#first-client\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">First client</a></li><li><a href=\"#quiz\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Quiz</a></li><li><a href=\"#glossary\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Glossary</a></li><li><a href=\"#red-flags\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Red flags</a></li><li><a href=\"#faq\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">FAQ</a></li></ul></div></nav><section class=\"px-5 pt-10 md:px-8\"><div class=\"mx-auto max-w-5xl\"><div id=\"plain-words\" class=\"rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><p class=\"eyebrow\">In plain words</p><p class=\"mt-3 max-w-3xl text-[1.0625rem] leading-[1.75] text-ink\">Most VAs never hear back because their applications read like everyone else’s. This course teaches you to write a short, specific application that a busy client actually reads — and answers.</p><div class=\"mt-6 grid gap-5 sm:grid-cols-2\"><div><p class=\"eyebrow text-muted\">This is for you if</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">You keep applying and getting silence. Or you freeze every time the box says ‘tell us why you’re a fit’.</p></div><div><p class=\"eyebrow text-muted\">You walk away with</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">A four-paragraph application formula, real job posts pulled apart, and templates you can adapt in ten minutes per job.</p></div></div></div></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"the-job\" class=\"scroll-mt-32\"><div class=\"space-y-5\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">You are not being rejected. In most cases you are not being read. A job post on Upwork commonly draws twenty to fifty proposals, and a decent OnlineJobs.ph post can pull hundreds. The person reading is skimming on a phone between meetings, and they are looking for a reason to stop.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">So this track is not about being more impressive. It is about being faster to understand. Every module here removes friction between the first line you write and the moment someone thinks \"this one actually read the post\".</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">We work from two fictional job posts all the way through: Harbor and Pine, a six-person interior design studio in Denver hiring an admin and ops assistant, and Tolliver Roofing, a family contractor in Ohio hiring someone to chase leads. Different worlds, same method. You will finish with a reusable format, a tracker, and a set of annotated rewrites you can steal from.</p></div><dl class=\"mt-10 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card shadow-tile\"><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">What this fixes</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Views with no messages, ghosting after the first reply, and copy-paste fatigue</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Target length</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">150 to 200 words. Two or three short paragraphs plus a closing line</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Daily volume</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Five tailored applications beats fifty pasted ones, every time</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Biggest single lever</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Applying as a specific role, not as \"a VA\"</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">What you end with</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">A format, 14 annotated rewrites, a tracker, and a follow-up script</dd></div></dl></section><section class=\"mt-16\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What a shift actually looks like</h2><ol class=\"mt-6 space-y-0\"><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">First 20 minutes</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Sourcing, not writing</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Collect eight to twelve posts worth applying to. Judge fit coldly. Skip the ones you would resent.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Next 10 minutes</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Triage the shortlist</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Drop anything posted over a week ago with no client activity, and anything with a scope you cannot name.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Core hour</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Five tailored applications</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Roughly ten minutes each. Same skeleton, different first line, different proof link.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">15 minutes</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Follow-ups</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Anything sent five to seven days ago with no reply gets one short nudge that adds new information.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">10 minutes</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Update the tracker</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Sent, viewed, replied, interviewed, offered. The numbers tell you which stage is broken.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Weekly</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Read your own rejections</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Same lane, same failure point? Then change one variable and run another 20 applications.</p></div></li></ol></section></div><section id=\"tools\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">The tools, and why each one exists</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Do not buy anything yet. Learn the free ones properly and use the client's licence for the rest — that is what everyone else is doing too.</p><div class=\"mt-8 space-y-8\"><div><p class=\"eyebrow text-muted\">Where the jobs are</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">OnlineJobs.ph</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The largest pool of employers specifically hiring Filipinos. Your ID Proof score matters here.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Upwork</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Higher ceiling, more competition, and Connects cost money. Best when you have samples.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">LinkedIn</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Underused by VAs. Recruiters search it, and a good headline pulls inbound messages.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Company career pages</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Remote-first companies hire directly and get a tenth of the applicants a marketplace does.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Staffing agencies</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Lower pay, faster placement. Sometimes the correct first move rather than the failure it feels like.</p></li></ul></div><div><p class=\"eyebrow text-muted\">What you send with it</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Loom</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">A 90-second intro video. Almost nobody sends one, and it settles the English question instantly.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Drive or Notion</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">One public-view folder with an index. Never send seven attachments.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Canva</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">A one-page mini-audit or sample report that looks deliberate rather than dashed off.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Sheets</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Your application tracker. Stage counts are the only way to diagnose what is failing.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Grammarly or a spellcheck pass</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Not for style. For the one typo in the first line that ends the read.</p></li></ul></div></div></div></section>"},{"kind":"slot","value":"MODULES","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"keep-learning\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Keep learning<span class=\"dot\" aria-hidden=\"true\">.</span></h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Hand-picked and free. These open in a new tab — official docs, academies and channels that go deeper on what this track teaches. No affiliate links, no sign-up walls.</p><ul class=\"mt-8 grid gap-3 sm:grid-cols-2\"><li class=\"h-full\"><a href=\"https://hemingwayapp.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Hemingway Editor</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Run every application through it. Shorter sentences get read.</p></a></li><li class=\"h-full\"><a href=\"https://www.grammarly.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Grammarly</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The free tier catches the typos that get applications silently binned.</p></a></li><li class=\"h-full\"><a href=\"https://www.onlinejobs.ph/blog\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">OnlineJobs.ph blog</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Written for employers too — read it to see what the other side is told to look for.</p></a></li><li class=\"h-full\"><a href=\"https://owl.purdue.edu/owl/job_search_writing/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Purdue OWL — job search writing</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">A university writing lab, free, with the fundamentals of letters that get replies.</p></a></li></ul></section></div>"},{"kind":"html","value":"<section class=\"border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><section id=\"rates\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What this actually pays</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">What to put in the rate field. These are general VA market observations from the OnlineJobs.ph April 2026 salary guide, adapted to what a client expects to see from a candidate at each stage of proof. Leaving the field blank or writing \"negotiable\" reads as no position at all.</p><div class=\"mt-7 rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><div class=\"space-y-7\"><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">No paid experience, has a proof folder</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">4–6<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:28.57142857142857%;width:14.285714285714285%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Ask for the top of this if your samples are specific to their business.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 640–960/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">One client or six months in a lane</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">6–9<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:42.857142857142854%;width:21.428571428571427%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">You can name a metric you moved. Quote a package, not an hour.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 960–1,440/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Specialist with references</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">10–14<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:71.42857142857143%;width:28.57142857142857%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">You are being chosen, not screened. Rate is a filter you apply to them.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 1,600–2,240/mo full-time</p></div></div></div><p class=\"mt-7 border-t border-line pt-4 text-[0.75rem] leading-relaxed text-muted-2\">Directional market benchmarks, not a guarantee and not a ceiling. Source: <a href=\"https://blog.onlinejobs.ph/comprehensive-guide-to-virtual-assistant-salaries-in-the-philippines\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">OnlineJobs.ph salary guide, April 2026</a>. Monthly figures assume 40 hours a week, which most VA roles are not.</p></div><div class=\"mt-5 rounded-2xl border border-[#f4d9c6] bg-clay-wash/70 p-6 sm:p-7\"><p class=\"eyebrow text-clay-deep\">What actually moves you up a band</p><ul class=\"mt-3.5 grid gap-2.5 sm:grid-cols-2\"><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>Your application quotes the post and names their tools</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You attach one artefact instead of describing five</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>Your profile headline names a buyer type</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You answer the rate question with a number and then stop talking</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You send a mini-audit before anyone asks for one</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You follow up once with new information rather than a nudge</li></ul></div></section></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><figure class=\"rounded-2xl border border-line bg-card p-7 shadow-card sm:p-9\"><figcaption class=\"flex flex-wrap items-center gap-3\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">Worker story</span><span class=\"text-[0.8125rem] text-muted\">One person's experience, not a universal rule</span></figcaption><h2 class=\"mt-4 font-display text-[1.5rem] font-semibold leading-snug text-ink\">\"I have a good resume and a portfolio and it is getting me nowhere\"</h2><blockquote class=\"mt-5 border-l-2 border-clay pl-5 font-display text-[1.1875rem] italic leading-relaxed text-ink\">“One mistake that every beginner does is they are all applying as a 'VA'. You have almost zero chance when you do this.”</blockquote><p class=\"mt-5 text-[0.9375rem] leading-relaxed text-ink-2\">In April 2026 someone posted on r/buhaydigital that they had wanted to be a VA for a long time, had learned that a resume was not enough, and had built a portfolio anyway with no experience. Still nothing. Their friends who succeeded had all been referred by someone they knew. Two replies did the real work. The first told them to stop applying as a generalist and to build a specific position out of whatever the portfolio actually shows, even a made-up role title. The second, from someone who hires Filipino VAs, said referrals dominating the market is the norm rather than the exception, that niche positioning like \"real estate cold caller\" or \"Shopify customer support VA\" gets traction far faster than \"experienced virtual assistant\", and that clients scan portfolios in about thirty seconds and want to see the work rather than read about it.</p><div class=\"mt-5 rounded-xl border border-teal-pale bg-teal-wash/60 p-4\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The lesson</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The poster was not lacking effort or credentials. They were lacking a category the buyer could recognise. If your application requires the client to work out what you would actually do on Monday, you have made your problem into their problem, and they have forty other messages.</p></div><a href=\"https://old.reddit.com/r/buhaydigital/comments/1sujt0f/so_hard_to_find_a_client_as_virtual_assistant/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"mt-4 inline-block text-[0.8125rem] font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">Read the original thread — r/buhaydigital, April 2026</a></figure></div><section id=\"first-client\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Getting the first one to say yes</h2><ol class=\"mt-7 space-y-4\"><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">01</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Fix the profile before you send another application</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Every message you send drives traffic to a page that is either working or leaking. Fix the leak first, then send volume through it.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">02</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Choose eight sources, not one</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">OnlineJobs.ph, Upwork, LinkedIn, two agencies, two remote-first company career pages, and one Facebook or Discord community in your lane. Marketplaces are the most crowded room in the building.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">03</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Build one artefact per lane, not per application</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Two hours once, reused fifty times, with the first paragraph swapped each time. This is the only way five tailored applications a day is survivable.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">04</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Answer the screening filter in the first line</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">If the post says start with a word, start with the word. Nothing else you write matters if you fail the filter they built to skip you.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">05</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Say the rate out loud in the first conversation</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">The longer you avoid it, the more the eventual number sounds like a demand. Named early, it is just a fact about you.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">06</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Ask for the referral explicitly</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">At the end of any rejection that felt human, ask one line: do you know anyone else who needs this. Referrals convert better than anything else in this market and cost one sentence.</p></div></li></ol><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">What goes in the portfolio</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">Every one of these comes out of the exercises above. Finish the track and you have the folder, not just the knowledge.</p><ul class=\"mt-5 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Two-minute Loom introduction</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Settles the English and communication question in the first thirty seconds.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A mini-audit of a real business in your lane</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Turns you from an applicant into someone already working on their problem.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">One before-and-after rewrite</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Instantly legible proof of judgment, which is the thing a resume cannot show.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A tracker or template they could use today</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Generosity that costs you nothing and reads as confidence.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A one-page sample weekly report</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Answers the unspoken fear: will I have to ask what is happening.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Your availability and response window, written down</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Removes the biggest unknown in hiring across time zones.</p></li></ul></div></section>"},{"kind":"slot","value":"QUIZ","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":""},{"kind":"slot","value":"GLOSSARY","wrappers":[{"tag":"section","class":"border-y border-line bg-paper-2/70 py-14 sm:py-20"},{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"red-flags\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Walk away when you see these</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Not every one of these is a scam. Some are just clients who will cost you more than they pay you, which ends the same way.</p><ul class=\"mt-7 space-y-3\"><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>The trial task is a full client deliverable with a deadline</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">That is not a test, that is a job you are doing for free. Offer a paid first week instead.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>They ask for your ID, selfie with ID, or bank details before any contract</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Documents come at contract stage, to a company you can verify. Before that it is identity harvesting.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Interview happens entirely over chat and you are hired within an hour</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">The speed is the scam. Real hiring involves at least one person's face.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>The post promises a very high rate for entry-level admin</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">The number exists to switch off your judgment before the request for money arrives.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>They ask you to apply through a link that wants your email password</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">No legitimate application ever needs your password to anything.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>The job post has no company name and refuses to give one</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">You cannot verify a ghost, and you certainly cannot chase one for unpaid invoices.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>They want you to sign an exclusive agreement before any paid work</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Exclusivity is something you sell, not something you give away for the chance to be considered.</p></li></ul></section></div><section id=\"faq\" class=\"scroll-mt-32 border-t border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Questions people actually ask</h2><div class=\"mt-7 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">How many applications should I send a day?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Five tailored ones. Fifty pasted ones produce fewer replies and, on platforms that measure response rate, actively damage you. If five feels slow, that is because you are building the artefact you will reuse for the next fifty.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Should I use AI to write my applications?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Use it to cut and to check, not to write. Clients read dozens of these and the smooth-and-empty register is now instantly recognisable. The whole edge here is the specific detail only you noticed, and no model noticed it for you.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Is it dishonest to put fictional client work in my portfolio?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">No, as long as every piece is clearly labelled as simulated work for a fictional company. Presenting invented results as a real client's outcome is the version that ends careers, and this market is small enough that it gets found out.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">The post says 3 years experience and I have none. Apply anyway?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Yes, if you can attach something that answers the objection. Years are a proxy for reliability, and an artefact is direct evidence. Skip it only when there is a hard requirement you genuinely cannot meet, like a licence or a specific time zone.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">How do I stop the ghosting from getting to me?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Keep stage counts. When you can see that your reply rate went from 2 to 9 percent, silence stops feeling like a verdict and starts looking like a conversion problem you are already solving. It is a real loss either way, just not a personal one.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Should I list my rate in my profile?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Yes, at the low end of the band you will accept. It filters out the clients who were never going to pay and it stops the conversation opening with a number they chose.</p></details></div><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">Where the facts in this course came from</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">All free, all worth your time. Open them in another tab and check us.</p><ul class=\"mt-5 space-y-2.5\"><li><a href=\"https://www.upwork.com/resources/how-to-create-a-proposal-that-wins-jobs\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Upwork: how to create a proposal that wins jobs</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">The platform's own guidance. Same shape as this course: their needs first, samples, two or three short paragraphs.</span></a></li><li><a href=\"https://blog.onlinejobs.ph/everything-you-need-to-know-about-idproof\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Everything you need to know about ID Proof</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Precisely which details raise your score, including the address and recent bill requirement.</span></a></li><li><a href=\"https://blog.onlinejobs.ph/what-can-you-do-to-increase-your-chances-of-getting-hired-at-onlinejobs-ph\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Increasing your chances of getting hired on OnlineJobs.ph</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Employer-side view of what a complete profile looks like and why incomplete ones get filtered.</span></a></li><li><a href=\"https://old.reddit.com/r/buhaydigital/comments/1sujt0f/so_hard_to_find_a_client_as_virtual_assistant/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">r/buhaydigital: so hard to find a client as a virtual assistant</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">The thread behind this track's worker story. Read the two long replies twice.</span></a></li><li><a href=\"https://blog.onlinejobs.ph/comprehensive-guide-to-virtual-assistant-salaries-in-the-philippines\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">OnlineJobs.ph salary guide</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Use it to pick the number you put in the rate field instead of writing negotiable.</span></a></li></ul></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-16\"><div class=\"rounded-2xl border border-line bg-clay-wash/60 p-7 sm:p-9\"><h2 class=\"font-display text-[1.5rem] font-semibold text-ink\">Finished? Go and use it.</h2><p class=\"mt-3 max-w-lg text-[0.9375rem] leading-relaxed text-ink-2\">The board updates every 30 minutes. Filter for this specialization, check your number against the rate tool, and send five tailored applications rather than fifty copy-pasted ones.</p><div class=\"mt-6 flex flex-wrap gap-3\"><a class=\"btn btn-primary\" href=\"/jobs\">See jobs on the board</a><a class=\"btn btn-ghost\" href=\"/pricing-tool\">Check your rate</a></div></div><div class=\"mt-10\"><p class=\"eyebrow text-muted\">Other written tracks</p><ul class=\"mt-3 flex flex-wrap gap-2.5\"><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/executive-assistant\">Executive Assistant</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/seo-specialist\">SEO Specialist VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/social-media-manager\">Social Media Manager VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/real-estate-va\">Real Estate VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/ecommerce-va\">E-commerce VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/complete-va-starter\">The Complete VA Starter</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/pricing-and-negotiation\">Pricing &amp; Negotiation</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/becoming-an-ops-lead\">Becoming an Operations Lead</a></li></ul></div><a class=\"btn btn-ghost mt-8\" href=\"/courses\">← All courses</a></div><!--$--><!--/$-->"}],"modules":[{"n":1,"title":"Why you get no replies","outcome":"You can name which of the four failure points is actually breaking your applications, instead of guessing.","badges":["Time split","Red/green flags"],"minutes":22,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">There are only four places an application dies: sourcing (wrong jobs), profile (they looked and left), message (they read and shrugged), or proof (they wanted evidence and found claims).</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Track the stages and the broken one is obvious. Lots of views and no messages is a profile problem. Lots of messages and no interviews is a proof problem.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The most common structural mistake is applying as a generalist. A Filipino VA answering someone with zero replies put it flatly: \"One mistake that every beginner does is they are all applying as a 'VA'. You have almost zero chance when you do this.\"</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Volume without tailoring makes the numbers worse, not better, because low-quality applications also lower your response rate on the platforms that measure it.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Referrals convert far better than cold applications, and that is not a reason to stop applying. It is a reason to tell every person you know your exact offer.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You are competing on clarity, not on credentials. Most of your competition is sending the same three paragraphs about being hardworking and detail-oriented.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Two months of applications, diagnosed</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Sent 180. Profile views 96. Replies 4. Interviews 1. Offers 0.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Read it backwards: the interview converted at 25 percent, which is fine, so interviewing is not the problem.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Replies at 4 out of 180 is roughly 2 percent. Below the 5 to 10 percent you should expect from tailored applications.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Views at 96 out of 180 means people are opening the profile, so the sourcing and the subject line are working.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Verdict: the profile and the message are the leak. Fix the headline and rewrite the opener, then run 30 more before changing anything else.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Without stage counts you would have concluded \"the market is hard\" and sent 180 more of the same thing.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Where the hours go</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">What happens to 100 applications on a typical job post</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A real-shaped funnel for a decent OnlineJobs.ph or Upwork post. Understanding where applications die tells you exactly what to fix.</p><div class=\"mt-4\"><div class=\"flex flex-col items-center gap-5 sm:flex-row sm:items-start sm:gap-7\"><svg viewBox=\"0 0 140 140\" class=\"h-[8.5rem] w-[8.5rem] shrink-0 -rotate-90\" role=\"img\" aria-labelledby=\"_R_b1lanpfiuqbtb_\"><title id=\"_R_b1lanpfiuqbtb_\">Never opened past the first line 52%, Opened, skimmed, discarded 26%, Read properly, no proof to back it up 12%, Shortlisted 7%, Interviewed 3%</title><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"var(--color-line)\" stroke-width=\"20\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#c3e6df\" stroke-width=\"20\" stroke-dasharray=\"182.96635614506957 168.89202105698726\" stroke-dashoffset=\"0\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#e07a2f\" stroke-width=\"20\" stroke-dasharray=\"91.48317807253478 260.37519912952206\" stroke-dashoffset=\"-182.96635614506957\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#5fd0bf\" stroke-width=\"20\" stroke-dasharray=\"42.223005264246815 309.63537193781\" stroke-dashoffset=\"-274.44953421760437\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#097769\" stroke-width=\"20\" stroke-dasharray=\"24.63008640414398 327.22829079791285\" stroke-dashoffset=\"-316.6725394818512\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#075f55\" stroke-width=\"20\" stroke-dasharray=\"10.555751316061704 341.3026258859951\" stroke-dashoffset=\"-341.30262588599516\"></circle></svg><ul class=\"w-full space-y-2\"><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#c3e6df\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Never opened past the first line</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">52%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Generic opener, obvious template, wrong role. Killed in under 3 seconds.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#e07a2f\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Opened, skimmed, discarded</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">26%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">All about the applicant, nothing about the client's problem.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#5fd0bf\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Read properly, no proof to back it up</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">12%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Good writing, but nothing to look at. Claims with no evidence.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#097769\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Shortlisted</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">7%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Specific, relevant, and had something the client could click.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#075f55\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Interviewed</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">3%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">The whole game is getting into this 3%. It's a writing problem, not a skills problem.</p></li></ul></div><p class=\"mt-4 border-t border-line pt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Roughly half of your competition is eliminated by the first sentence. That's not depressing — it means the first sentence is where nearly all your leverage is, and it's the cheapest thing to fix.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">The opening line of your application</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"Dear Sir/Madam, I hope this message finds you well. My name is [name] and I am writing to apply for the Virtual Assistant position you posted. I believe I would be a great fit for this role.\"</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Thirty-eight words containing zero information. They know it's an application — they posted the job. Every one of the other 99 applicants opened this way, which means you've just made yourself indistinguishable from all of them.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"You mentioned you're losing evenings to your inbox. I took a founder's inbox from 200+ daily to under 10 and gave him back two mornings a week — here's exactly how I did it: [link].\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Names THEIR problem in the first six words, follows with a specific result and a number, and gives them something to click. They now have a reason to read line two.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">How you talk about your experience</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"I have 3 years of experience as a virtual assistant. I am hardworking, detail-oriented, a fast learner, and I can work with minimal supervision. I am proficient in Microsoft Office and Google Workspace.\"</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Every adjective here is unverifiable and universal. Nobody applies saying they're careless and slow. Claims without evidence are noise, and \"proficient in Google Workspace\" is the modern equivalent of listing 'can use a telephone'.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"Three years running ops for a 4-person agency. Concretely: I rebuilt their client onboarding from a 12-day mess to a 3-day checklist, and cut invoice chasing from ~6 hrs a week to under 1 by automating the reminders. Both are in my portfolio.\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Same three years, but described in changes with numbers attached. Nobody can argue with a specific before and after, and nobody else's application will contain those exact sentences.</p></div></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build the tracker: date, company, role, source, rate asked, sent, viewed, replied, interviewed, outcome, and a notes column.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A Sheets tracker with your last 20 applications entered honestly, plus your conversion rate at each stage.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 40 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">You calculated a percentage at each stage, not just totals</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">You named the single weakest stage</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">You wrote one hypothesis for why that stage is weak</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">The tracker takes under 30 seconds per new row</span></label></li></ul></div>"},{"n":2,"title":"Read the post like the person who wrote it","outcome":"You can extract the real pain, the hidden requirement, and the one line worth quoting back, in three minutes per post.","badges":["Workflow","1 template"],"minutes":26,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Job posts are written by tired people describing a bad week. Find the bad week and you have found your opening line.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Separate the must-haves from the wish list. Anything mentioned twice, or attached to a number, is a must-have.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Look for the tell: an oddly specific complaint, a tool named in passing, a deadline, a sentence in a different tone. That is the human breaking through the template.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Note what they did not say. No mention of hours, rate, or reporting line usually means they have not thought it through, which is an opportunity to look organised.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Screening instructions buried in the post are a filter. Ignore them and you are auto-rejected regardless of quality. Follow them exactly, first line.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Decide fit before you write. If you cannot state the outcome they want in one sentence, you cannot write a good first line, so skip the post.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Harbor and Pine's post, decoded</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Looking for a reliable admin/ops assistant for our small interior design studio. Must be organised and proactive. Duties include managing our project tracker, coordinating with vendors and contractors, processing invoices in QuickBooks, and handling client emails. We're growing fast and things fall through the cracks. Must overlap with Mountain Time mornings. Please start your reply with the word 'Aspen'.\"</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Real pain: things fall through the cracks. Not admin. Follow-through.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Must-haves: project tracker ownership, vendor coordination, QuickBooks invoices, client email, Mountain Time morning overlap.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Hidden requirement: they will need you to chase contractors, which is confrontation work, which is why the last person quit.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Screening filter: the reply must start with \"Aspen\". This alone removes most of the pile.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Quotable line: \"things fall through the cracks\". Use their words, not yours.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Unsaid: no hours, no rate, no mention of who you report to. Offer structure and you look like the safe hire.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Three minutes of reading produced an opening line, a proof piece to attach, and a question that makes you sound experienced.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Reading a job post properly, in four minutes</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Before writing a single word of any application.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Find the pain, not the task list</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Somewhere in the post is a sentence written in frustration. \"Things keep falling through the cracks.\" \"I need someone who won't need constant reminders.\" That sentence is what they're actually buying.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Note the exact words they use</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">If they say \"clients\" not \"customers\", or \"deals\" not \"projects\", mirror it. Echoing someone's vocabulary is the cheapest rapport there is.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Find the hidden requirement</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Timezone overlap, a specific tool, an industry. These are usually mentioned once, in passing, and they're the actual filter.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Spot the screening trap</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Many posts hide an instruction — \"start your reply with the word BANANA\", \"tell me your favourite book\". Missing it is an instant, automatic rejection and it's the easiest filter to pass.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Judge who wrote it</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A founder writing at midnight, an HR person, or an agency recruiter? Each wants a completely different tone. Founders want directness; HR wants the requirements matched.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Decide honestly whether to apply</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">If you match under half the real requirements or the rate is under your floor, skip it. Applying to everything is how you get a 2% reply rate and conclude the market is bad.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Skimming for the job title and rate, then writing from a template. The four minutes spent reading properly is what produces the specific first line, and the specific first line is the whole application.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Job post decode sheet</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Fill this in before writing. Two minutes, and the application almost writes itself afterwards.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>POST: [title] | Company: [name] | Rate: [posted] | Source: [board]\n\nWHAT THEY LITERALLY ASKED FOR\n1. [requirement]\n2. [requirement]\n3. [requirement]\n\nWHAT THEY ACTUALLY WANT (the pain underneath)\nThe line that gives it away: \"[quote it exactly]\"\nWhat that means: [e.g. \"the last VA needed managing, and managing them cost more time than they saved\"]\n\nTHEIR VOCABULARY — mirror these words\n[word] not [word] · [word] not [word]\n\nHIDDEN REQUIREMENTS\nTimezone: [what they need]\nTool they named: [tool]\nIndustry knowledge: [any]\nScreening instruction buried in the post: [find it — reread the last paragraph]\n\nWHO WROTE THIS\n[ ] Founder — be direct, lead with outcomes, keep it short\n[ ] HR/recruiter — match the requirements explicitly, be a bit more formal\n[ ] Agency — emphasise reliability, process, and low management overhead\n\nMY ANGLE\nThe one thing I'll lead with: [the single most relevant proof I have]\nThe gap I have: [be honest] → how I'll address it: [one line, no excuses]\n\nAPPLY? [Y/N]\nRule: skip it if I match under half the real requirements, or the rate is below my floor.\nApplying anyway \"just in case\" is what makes the funnel numbers meaningless.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Decode five live job posts in your lane using the six headings above: pain, must-haves, hidden requirement, screening filter, quotable line, unsaid.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A decode sheet with five rows, one per post.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 45 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">Each pain is written in the client's own words</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">You found at least one screening instruction across the five</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">You marked at least one post as a skip, with the reason</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">No hidden requirement is just a restatement of a listed duty</span></label></li></ul></div>"},{"n":3,"title":"The profile they check before they reply","outcome":"Your profile answers the three questions a client has in the eight seconds after your message lands.","badges":["Red/green flags","1 template"],"minutes":26,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">They read your message, then they check your profile, then they decide. A great message with an empty profile dies at step two.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Your headline is not your job title. It is your offer: what you do, for whom, and the result. \"Admin and ops support for small design and build studios: trackers, vendors, invoices\" beats \"Virtual Assistant | Data Entry | Social Media\".</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">On OnlineJobs.ph, ID Proof is a real gate. Fill in everything the site asks for, including a photo, government ID, your Facebook URL, your address with a supporting bill dated within the last three months, and written skill descriptions. More verified detail means a higher score, and many employers filter out low scores before reading.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Skill descriptions should be sentences about work you have done, not a keyword list. Keywords help you get found and sentences get you hired.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use one professional photo where your face is clear. Not a group shot, not a filter, not a logo.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">On LinkedIn, write the headline for the recruiter's search box. If nobody searches for the words in your headline, nobody finds you.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Headline and summary, before and after</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Headline: \"Virtual Assistant | Hardworking | Data Entry | Social Media Manager | Canva\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Summary: \"Hi! I am a passionate and hardworking virtual assistant with strong attention to detail. I am willing to be trained and can work with minimal supervision. I am proficient in MS Office, Google Workspace, Canva, and social media platforms.\"</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Headline: \"Admin and ops support for small design and construction studios. Project trackers, vendor chasing, QuickBooks invoicing.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Summary: \"I keep small project-based businesses from losing work in the gaps. For a six-person studio that means the tracker is current every morning, vendors get chased before the client notices a delay, and invoices go out on the same day each week rather than whenever someone remembers. I work 7am to 12pm Mountain Time, reply within two hours in that window, and send a Friday summary of everything moved, stalled, and waiting on a decision. Tools: Asana, QuickBooks, Google Workspace, Slack. Samples in the link below.\"</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The rewrite makes no claims about being hardworking. It describes a week. A client can picture buying that.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Your profile headline</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"Virtual Assistant | Data Entry | Social Media | Customer Service | Admin Support | Lead Generation | Graphic Design\"</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">A list of everything is a claim to nothing. A client looking for an ecommerce ops person sees a generalist and moves on, because someone whose profile says \"Ecommerce Ops\" looks more likely to be good at it.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"Ecommerce Ops VA — Shopify + Amazon | I keep stores from running out of stock and customers from waiting\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">One lane, and the second half describes the outcome the client cares about rather than the tasks you perform. Narrow feels like it's shutting doors. It's actually the only way to be chosen.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Your profile photo and intro video</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">No photo, or a heavily filtered selfie, or a group photo cropped down. No video at all.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Hiring someone across the world is an act of trust, and there's no photo of you. The absence reads as either inexperience or something to hide. Most applicants skip the video, which is precisely why it works.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">A clear, well-lit photo of your face against a plain wall, taken on a phone. Plus a 60–90 second video: your name, your lane, one specific thing you did, and your working hours. No script read aloud.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">A video removes almost all of the client's uncertainty about your English, your setup, and whether you seem like a functioning professional. It's the single highest-conversion asset you can build, and it takes an afternoon.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Profile rewrite worksheet</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Do this once properly, then use the same wording across OnlineJobs.ph, Upwork and LinkedIn.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>HEADLINE (under 70 chars)\nFormula: [Lane] VA — [tools] | [the outcome you produce]\ne.g. \"Executive Assistant — inbox &amp; calendar | I give founders their mornings back\"\n\nTest it: could 50 other applicants use this exact headline? If yes, rewrite.\n\nOVERVIEW — first two lines are all most people read\n\nLine 1: The problem you solve, in their words.\n\"Most founders I work with are losing 2 hours a day to an inbox they're scared to close.\"\n\nLine 2: What you do about it, with a number.\n\"I run inbox and calendar so that stops. Last client: 200+ unread daily down to under 10, held there for 8 months.\"\n\nThen:\n• What you specifically do (4–6 bullets, all outcomes, no adjectives)\n• Tools you'd be happy to be tested on\n• Your hours, in the CLIENT's timezone\n• One line of personality — you're a person, not a service\n\nClose with a clear next step:\n\"Portfolio: [link]. 90-second intro: [Loom]. Happy to do a paid trial task.\"\n\nWORDS TO DELETE ENTIRELY\nhardworking · detail-oriented · fast learner · passionate · dedicated · team player\n\"I can do anything you need\" · \"minimal supervision\" · \"I hope this finds you well\"\nEvery one of these appears in the majority of applications, so they carry no information.\n\nWORDS THAT WORK\nNumbers. Tool names. Timezones. Specific outcomes. The client's own vocabulary.\n\nTHE PHOTO\nPlain wall, face lit from the front, phone camera, no filter, slight smile. 20 minutes.\n\nTHE 90-SECOND VIDEO — script skeleton (talk it, don't read it)\n0:00 \"Hi, I'm [name], I'm a [lane] VA based in the Philippines.\"\n0:08 \"I work with [type of client] on [the specific thing].\"\n0:20 \"Here's an example: [one concrete story with a number].\"\n0:50 \"I work [hours] [client's timezone] and I'm on [speed] fibre with a backup connection.\"\n1:05 \"Portfolio's linked below. Happy to do a paid trial so you can see how I work.\"\n\nRecord it 5 times, use take 4. Do not script it word for word — it always sounds read.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Rewrite your headline and summary for your chosen lane, then complete every field on OnlineJobs.ph and check your ID Proof score after a day.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: Screenshots of the old and new profile, plus your ID Proof score before and after.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 60 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">The headline names a buyer type and at least two concrete deliverables</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">The summary describes a normal week, not your personality</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">Every ID Proof field is filled, including address with a recent bill</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">The photo is a clear head and shoulders shot</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">Your samples link is public-view and tested in a private window</span></label></li></ul></div>"},{"n":4,"title":"The four-paragraph format","outcome":"You can write a 180-word application in ten minutes that reads as if it took an hour.","badges":["2 templates"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The skeleton: their problem in their words, the specific thing you would do about it, one piece of proof, then a low-friction close.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Paragraph one is the whole game. Do not open with your name, your years of experience, or the word \"passionate\". Open with the outcome they want.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Paragraph two must contain something only someone who read the post could write. A named tool, a named constraint, a first-week action.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Paragraph three is proof, and one link beats four. Say what the link is and what it shows.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Paragraph four gives them the easiest possible yes: your availability window, your rate if requested, and one question they can answer in a sentence.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Upwork's own guidance is the same shape: address the client's specific needs in the opening lines, include relevant samples, keep it to two or three short paragraphs. Everyone knows this and almost nobody does it.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The full application to Harbor and Pine</p><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Aspen.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Things fall through the cracks\" is usually a follow-up problem rather than an admin problem, and it is the part I am good at. For a six-person studio, the fix is a tracker that is current before the owner opens it and a chase list that runs on a schedule instead of on memory.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">In my first week I would take over the project tracker, add a last-touched date to every vendor and contractor line, and start a daily 15-minute chase pass on anything untouched for three days. Invoices would go out the same day each week in QuickBooks rather than in a batch when someone notices.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Here is a chase tracker I built for a fictional design studio, with the formula that flags anything silent for 72 hours: [link]. Same folder has a one-page Friday summary in the format I would send you.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">I work 7am to 12pm Mountain Time and reply within two hours in that window. One question: when a contractor goes quiet, do you want me chasing them directly under my own email, or drafting for you to send?</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">One hundred and eighty words. It quotes them, names their tools, commits to a first week, links one artefact, and ends with a question only a real candidate would think to ask.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">The four-paragraph application</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">The whole format. Under 200 words. Longer applications do not perform better — they perform worse.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[No \"Dear Sir/Madam\". Use their name if you can find it, otherwise no greeting at all.]\n\nPARAGRAPH 1 — THEIR PROBLEM (1–2 sentences)\nProve you read the post. Name the specific pain, using their words.\n\"You said things keep slipping between the cracks when you travel. That's usually a follow-up problem, not a calendar problem.\"\n\nPARAGRAPH 2 — PROOF YOU'VE SOLVED IT (2–3 sentences)\nOne specific example with a number. Not your whole CV. One.\n\"I ran the follow-up system for a 4-person agency for two years. Every commitment made in a meeting went into a tracker with an owner and a date, chased 3 days early. Nothing was dropped in 18 months, including during two directors' parental leave.\"\n\nPARAGRAPH 3 — WHAT I'D DO IN WEEK ONE (2–3 sentences)\nFree thinking. This is the paragraph almost nobody writes, and it's why it works.\n\"First week I'd build your waiting-for list from your sent folder — everything you've asked someone for that hasn't come back. That's usually 15–20 things nobody is tracking. Then a daily EOD note so you know where everything stands without asking.\"\n\nPARAGRAPH 4 — LOGISTICS + ONE CLEAR NEXT STEP (2 sentences)\n\"I'm available 6am–2pm PST, [n] hrs a week, at $[n]/hr. Portfolio's here [link] and there's a 90-second intro if useful [link] — happy to do a paid trial task on a real piece of your inbox.\"\n\n[Screening word if the post asked for one — put it exactly where they said.]\n\nRULES\n• Under 200 words total. Count them.\n• Their name in the first line if you can find it. Check the website's About page.\n• One number minimum, ideally two\n• One link they can click without signing up for anything\n• A specific rate. \"Negotiable\" reads as \"I don't know what I'm worth.\"\n• Never attach a CV unless asked. It's a reason to stop reading.\n• Read it out loud before sending. If you'd be embarrassed to say it, rewrite it.</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Three openers that get read</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">The first sentence does 80% of the work. Pick the shape that fits what the post revealed.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>1. THE PROBLEM MIRROR — when they described a pain\n\"You mentioned [their exact pain]. That's almost always [your diagnosis], and it's fixable in about [timeframe].\"\n\nExample: \"You mentioned the last VA needed constant reminders. That's usually a documentation problem rather than an attitude one — a person with a checklist doesn't need reminding.\"\n\n2. THE RESULT OPENER — when you have a close-matching win\n\"[Specific result with a number]. Here's how, in case it's useful for [their situation]: [link]\"\n\nExample: \"Took a Shopify store's support queue from 3-day replies to under 4 hours without adding headcount. Wrote up exactly how here, in case it's useful for your 600-orders-a-month setup: [link]\"\n\n3. THE OBSERVATION OPENER — when you've actually looked at their business\n\"[Something specific and true you noticed]. [What it means]. [What you'd do.]\"\n\nExample: \"Your product pages don't have a size chart, and three of your recent reviews mention sizing confusion. That's usually worth a couple of points of conversion and it's a one-afternoon fix.\"\n\n⚠ The observation opener is the strongest by a distance, and the riskiest.\nIt requires you to genuinely look at their business for ten minutes.\nBe helpful, never smug. \"You've made a mistake\" loses; \"here's something free\" wins.\nNever open by criticising something they're obviously proud of.\n\nNEVER OPEN WITH\n\"I hope this email finds you well\"\n\"My name is...\" (it's in the From field)\n\"I am writing to apply for...\" (they know)\n\"I came across your job posting...\" (obviously)\n\"I am the perfect candidate for this role\" (you can't know that yet)</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write three applications to three live posts using the four-paragraph skeleton. Time yourself on each.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: Three applications, each under 200 words, with the time taken noted.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 50 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">No application opens with your name or your years of experience</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Each contains one detail that could only come from reading that post</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Exactly one proof link, described in the sentence before it</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The closing question is answerable in under ten words</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The third one took you under twelve minutes</span></label></li></ul></div>"},{"n":5,"title":"Fourteen rewrites","outcome":"You have a library of annotated before-and-after lines and you can spot the failure mode in your own drafts.","badges":["Red/green flags","1 template"],"minutes":34,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Most bad applications fail in one of six ways: they are about you, they are generic, they are too long, they beg, they overclaim, or they make the client do work.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The fastest fix for any weak opener is to delete the first sentence. It is almost always throat-clearing.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never use the phrase \"I am the perfect fit\". Show the fit and let them conclude it. Asserting it is what people with nothing to show do.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Do not apologise for lacking experience. Substitute proof. \"I have not worked in real estate, but here is a CRM cleanup I built on sample data\" is a strong sentence. \"I have no experience but I am willing to learn\" is a weak one.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Enthusiasm is not a qualification. Exclamation marks do not raise your reply rate, and three of them lower it.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Cut every sentence that would survive a copy-paste into a different application. If it fits everywhere it persuades nowhere.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Fourteen lines, annotated</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">1. \"Hi! My name is ___ and I am a passionate and hardworking virtual assistant.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">2. \"I saw your job post and I am very interested in this position.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">3. \"I am a fast learner and can work with minimal supervision.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">4. \"I have 3 years of experience in various administrative tasks.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">5. \"I believe I am the perfect fit for this role.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">6. \"I don't have experience in real estate, but I am willing to be trained.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">7. \"Please consider my application. It would mean a lot to me and my family.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">8. \"I am proficient in MS Office, Google Workspace, Canva, and CRM tools.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">9. \"I can start immediately and I am available 24/7.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">10. \"Attached is my resume for your review.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">11. \"I am willing to accept any rate you offer.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">12. \"I have helped many clients grow their business.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">13. \"Looking forward to your positive response. God bless!\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">14. \"Let me know if you have any questions.\"</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">1. \"Aspen. Your tracker being out of date by Wednesday is the thing I would fix first.\" Opens on their problem, not your name.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">2. \"You mentioned invoices go out whenever someone remembers. I would move them to a fixed Thursday run.\" Interest is proven by specificity, never announced.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">3. \"I learned Follow Up Boss in a weekend and rebuilt a 400-contact pipeline on sample data: [link].\" Replace the claim with the evidence for it.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">4. \"For three years I ran the vendor chase list for a construction firm, average response time down from 6 days to 2.\" Three years of what, producing what.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">5. Delete entirely. Nothing replaces it. The client decides fit; your job is to make the decision easy.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">6. \"New to real estate, so I built the thing first: a CRM cleanup and speed-to-lead SOP on sample data: [link].\" Answer the objection with an artefact.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">7. \"Happy to do a paid first week so you can judge the work rather than the application.\" Need is not persuasive. Reduced risk is.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">8. \"QuickBooks for invoicing, Asana for the tracker, and I will use your Slack conventions rather than mine.\" Name their stack, not the alphabet.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">9. \"7am to 12pm Mountain Time, replies within two hours in that window.\" 24/7 reads as desperate and unsustainable, and both are true.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">10. \"One link, not attachments: [folder]. Top item is a two-minute Loom of how I would run your first week.\" Make it one click on a phone.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">11. \"$8 an hour for the scope in your post, and I will tell you if something you add should change that.\" A number reads as a professional. Anything reads as a warning.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">12. \"For one client that meant 38 quotes a month answered inside an hour instead of a day.\" One client, one number, one timeframe.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">13. \"One question: chase contractors under my email, or draft for you?\" End with a door, not a blessing.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">14. Delete. Replace with a specific question. \"Any questions\" pushes the work back to the person with less time than you.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Every rewrite does the same two things: it removes a claim about you and adds a fact about them or a link they can click.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Applying when you don't meet every requirement</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"I don't have direct experience with Klaviyo, but I'm a very fast learner and I'm confident I could pick it up quickly. I'm sure I could figure it out.\"</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Three hedges in two sentences, and no evidence. \"Fast learner\" is what everyone says, and \"figure it out\" tells the client they'll be paying for your learning time.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"I haven't used Klaviyo on a paid account. I've built the same flows in Mailchimp — abandoned cart, welcome series, post-purchase — and I spent this weekend building a Klaviyo test account with those three flows so I could see the differences. Here's the screenshot [link]. I'd expect a week to be genuinely fast in it.\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Honest about the gap, proves the transferable skill, shows you did unpaid work to close it, and gives a realistic timeline. This beats an applicant who actually has Klaviyo experience but describes it vaguely.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Following up after no reply</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"Hi, just following up on my application. Did you get a chance to review it? Looking forward to hearing from you.\" — sent every two days for two weeks.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Adds no information and creates work for them. Repeated content-free follow-ups actively move you down the list, because now you're a person who will pester.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Once, after 5–7 days: \"Following up on the EA role. Since applying I put together a quick version of the waiting-for list I mentioned, using a fake inbox — [link]. Should give you a sense of how I'd approach week one. Happy to leave it there if you've filled the role.\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">One follow-up, and it carries new value rather than a request. The graceful exit line removes any pressure, which paradoxically makes people more likely to reply.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Rewrites: the same sentence, weak and strong</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Read your draft and search for these patterns. They're in almost every rejected application.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>❌ \"I am hardworking and detail-oriented.\"\n✅ \"I ran a 340-row product import with zero errors by testing 3 rows first — the checklist I used is in my portfolio.\"\n\n❌ \"I have experience with social media management.\"\n✅ \"I ran two IG accounts for 14 months, 12 posts a month each, and grew DM enquiries from 8 to 40 a month on the larger one.\"\n\n❌ \"I am a fast learner and can pick up new tools quickly.\"\n✅ \"I learned Gorgias in a weekend on their free tier and built 7 macros. Screenshot in my portfolio.\"\n\n❌ \"I can work with minimal supervision.\"\n✅ \"I send an EOD summary daily — done, decided, blocked, needs you. You'd never need to ask where something is.\"\n\n❌ \"I am available to start immediately and flexible with hours.\"\n✅ \"I work 6am–2pm PST, Mon–Fri. That's a 5-hour overlap with your morning. I can start Monday the 14th.\"\n\n❌ \"I would love the opportunity to work with your company.\"\n✅ \"Happy to do a paid trial on a real task so you can see how I work before committing.\"\n\n❌ \"Please find my resume attached for your consideration.\"\n✅ \"Portfolio's here: [link]. Three worked examples, takes about four minutes.\"\n\n❌ \"I have excellent English communication skills.\"\n✅ [Delete this and record a 90-second video instead. Claiming good English in writing is the weakest possible proof of it.]\n\n❌ \"My rate is negotiable.\"\n✅ \"$8/hr, or $1,200/month for 35 hrs/week.\"\n\n❌ \"I hope to hear from you soon. Thank you for your time and consideration.\"\n✅ \"If it's useful I'll send over how I'd handle your first week — just say the word.\"\n\nTHE TEST FOR EVERY SENTENCE\nCould a bad applicant write this exact sentence honestly?\nIf yes, it's doing no work for you. Cut it or make it specific.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Take three of your own past applications and mark every sentence with one of the six failure modes. Then rewrite them.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A before and after document with your annotations visible.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 50 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Every original sentence is labelled with a failure mode or marked as fine</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">At least a third of the original words are gone</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">No rewritten line could be pasted into a different application unchanged</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You cut every exclamation mark</span></label></li></ul></div>"},{"n":6,"title":"Proof that does the arguing for you","outcome":"You can build a two-hour mini-audit or sample that makes the reply almost automatic.","badges":["Workflow","Red/green flags","1 template"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The highest-converting attachment is unpaid work aimed at their actual business, capped at two hours. Not a free month. A sample.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A mini-audit has three parts: three things you noticed, one you would fix first, and how you would measure that it worked. Half a page.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Do not send a critique that makes them feel stupid. Frame it as \"here is what I would do in week one\", not \"here is what is wrong with you\".</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">For any lane you can build a sample on invented data in an afternoon: a CRM cleanup, an inbox taxonomy, a content calendar, a returns workflow, a keyword map.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">One VA who hires described how clients read portfolios: they scan for about thirty seconds and want to see the work, not read about it. Lead with the artefact, not the explanation.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Label everything simulated as simulated. Passing off invented results as a real client's is the one lie that ends a career in a market this small.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The two-hour mini-audit for Tolliver Roofing</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Noticed 1: your contact form sends to a shared Gmail with no auto-reply, so a homeowner hears nothing until someone opens it.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Noticed 2: your Google Business Profile has 31 reviews and 4 unanswered, the newest from March.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Noticed 3: the quote request form asks for eight fields including budget, which is where most people abandon a roofing form.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Fix first: speed to lead. An auto-reply within 60 seconds with a booking link, then a human reply inside an hour during working days.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Measure: time from form submission to first human reply, tracked weekly. Baseline it in week one and report the median.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Attached: the auto-reply copy and a one-page tracker template, both ready to use whether or not you hire me.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Two hours of work, no access required, and it changes the conversation from \"can you do admin\" to \"when can you start on speed to lead\".</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Building proof when you have no clients yet</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The chicken-and-egg problem. You need experience to get hired, and hiring to get experience.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Build for a fictional client, and label it clearly</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A practice scenario shown in full beats a real client you can't discuss. The honesty is itself a selling point — say \"practice scenario\" and clients respect it.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Fix something real for a real business, unasked</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Find a local business, spend an hour, send them the improvement for free. Even if they ignore it, you now have a genuine artefact about a genuine business.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Do one small job cheap, deliberately, once</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">One underpriced project purely to generate a testimonial and a case study. Once. Not a strategy — a transaction where the payment is the proof.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Show the thinking, not just the output</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A pretty deliverable proves you can use Canva. A note explaining why you made the tradeoff proves you can think, which is what actually gets you hired above $6/hr.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Record a walkthrough of everything</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Three minutes on a Loom talking through your work converts better than the work sitting silently in a folder.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Put it all behind ONE link</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A view-only Notion page or Google Doc. One link, in the first paragraph of every application, forever.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Waiting until the portfolio is impressive. Three modest, clearly-explained artefacts published today beat a perfect portfolio you're still building in six months.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">How you present practice work</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Presenting a practice scenario as though it were a paid client, hoping nobody asks. Or hiding it entirely because \"it's not real work\".</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Getting caught inventing a client ends the conversation and the reputation instantly. And hiding it means you're applying with nothing at all, which is worse than applying with honest practice work.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"Note: Mara Villaflor is a practice scenario from my training, not a paid client — which is exactly why I can show you every artefact in full rather than a redacted summary.\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Turns the apparent weakness into an actual advantage. Real client work is usually confidential and can only be described vaguely. Practice work can be shown completely, and completeness is what convinces.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Case study format</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">One page per artefact. Situation, action, result, thinking. The last section is the one that gets you hired.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[TITLE — describe the RESULT, not the task]\n❌ \"Inbox management project\"\n✅ \"212 unread emails to 6, held there for a month\"\n\n[If practice work, say so in the first line. Always.]\nPractice scenario from my training. Not a paid client — so I can show you all of it.\n\nTHE SITUATION (2–3 sentences)\n[What was broken and why it mattered. Concrete. \"A founder with 212 unread emails who'd stopped opening his inbox before 11am because it made him anxious. Two client questions had gone unanswered for over a week.\"]\n\nWHAT I DID\n1. [Action] — [why this first]\n2. [Action] — [why]\n3. [Action] — [why]\n\n[Screenshot or embed of the actual artefact]\n\nTHE RESULT\nBefore: [number] → After: [number]\n[Second measure]: [before] → [after]\nTime it took: [n] hours\nOngoing time to maintain: [n] mins/day\n\nTHE THINKING — the section that actually matters\n[The judgment call you made and why. This is what separates you from someone who can follow a tutorial.]\n\"The tempting move was to reply to everything. I didn't — I sorted all 212 first without writing a word, because replying as you read means spending 40 minutes on email #3 and never reaching the urgent one at #90. Sorting first took 20 minutes and made the rest obvious.\"\n\nWHAT I'D DO DIFFERENTLY\n[One honest thing. Nobody believes a flawless case study, and admitting a limitation makes the rest more credible.]\n\n[Loom walkthrough: link]</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Pick one real business in your lane and build a mini-audit on public information only. No logins, no guessing at private data.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A half-page audit plus one usable template, both clearly marked as unsolicited and free to keep.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 2 hours</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Everything you noticed is verifiable from public information</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The fix names a metric and a baseline</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Nothing in it insults the owner</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The attached template is usable without hiring you</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You capped yourself at two hours</span></label></li></ul></div>"},{"n":7,"title":"Interviews, tests, and trial tasks","outcome":"You can handle the screening call, answer the rate question, and tell a fair trial from free labour.","badges":["Red/green flags","2 templates"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The first call is mostly a check that you are real, you communicate clearly, and your setup works. Test your audio beforehand and sit somewhere quiet.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Have three stories ready in the shape of situation, what you did, and the result. Recycle them. Interviewers are not comparing notes with each other.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">When they ask about a gap or missing experience, answer in one sentence and pivot to evidence. Long explanations sound like guilt.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The rate question is answered with a package, not a number in the air: \"For the scope in your post, roughly 20 hours a week, my rate is $X an hour and I invoice biweekly.\" Then stop talking.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A fair trial task takes one to three hours, is scoped in writing, and is paid or clearly agreed as unpaid in advance. An unfair one is a real deliverable for a real client with a real deadline.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Ask your own questions: who else does this work today, what does a good first month look like, and how will you know I am doing well. Candidates who ask these read as senior.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The rate question, three ways it goes</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Client: \"So what's your rate?\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">You: \"Um, what's your budget? I'm flexible, whatever works for you.\"</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Version A, they asked first: \"For the scope in your post, around 20 hours a week covering the tracker, vendor chasing and weekly invoicing, my rate is $8 an hour and I invoice biweekly.\" Then say nothing.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Version B, they push back: \"I hear you. At $6 I would keep the tracker and the invoicing and drop the vendor chasing, since that is the piece that eats the hours. Which shape do you want?\" Reduce scope, do not discount.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Version C, they name a number first and it is low: \"That works for the tracker and invoicing only. If you want vendor chasing included it is $8. Both are real offers, your pick.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">In all three you gave a number, kept a boundary, and never once said the word sorry.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Reflecting the question back with \"what's your budget\" tells the client the price is whatever they say. You will never recover from that opening.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">They ask you to do a trial task</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Accepting a 6-hour unpaid \"test project\" that is obviously real client work with a real deadline, because you don't want to seem difficult.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Some clients split one real job into unpaid \"tests\" across several candidates and get it done for free. The tell is real deliverables, real deadlines, and real client names.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"Happy to do a trial — it's the best way for both of us to check the fit. For something this size I'd charge [rate] for the [n] hours. If it's a shorter sample, say 30–45 minutes on something anonymised, I'm glad to do that free. Which works for you?\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Agrees enthusiastically to the principle, draws the line at scale rather than at the idea, and offers a free alternative. A real client says yes to one of those. A free-labour operation goes quiet.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">The interview asks about your weakness or a mistake</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"My weakness is that I'm a perfectionist and I work too hard.\" Or: \"I can't really think of any mistakes.\"</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">The first is a non-answer everyone recognises and it signals you're managing them rather than being honest. The second is either untrue or means you haven't done enough to have made mistakes.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"I used to under-communicate when I was stuck. I'd try to solve it alone to avoid looking incompetent, and a deadline slipped because of it. Now I flag anything blocked within 2 hours, with what I've already tried. It felt like admitting weakness at first and it turned out clients much prefer it.\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">A real weakness, a real consequence, a specific behaviour change, and evidence it stuck. This answer builds more trust than any strength you could name.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Interview prep sheet</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Fill this in before every interview. Twenty minutes, and you stop improvising under pressure.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>COMPANY: [name] | ROLE: [title] | INTERVIEWER: [name, role] | [date/time + BOTH timezones]\n\nRESEARCH — 15 minutes, no more\nWhat they sell: [one line]\nWho to: [one line]\nSomething specific I noticed: [a recent post, a product, a page — proves I looked]\nTheir likely biggest operational headache: [my guess]\n\nMY THREE STORIES — have these ready, don't recite them\n1. A time I fixed something: [situation → what I did → number]\n2. A time I made a mistake: [what → impact → what changed → evidence it stuck]\n3. A time I handled a difficult person: [situation → how → outcome]\n\nMY NUMBERS — say these without hesitating\nRate: $[n]/hr or $[n]/month for [n] hrs\nAbsolute floor: $[n] (do NOT say this out loud, just know it)\nHours available: [specific, in THEIR timezone]\nStart date: [date]\n\nQUESTIONS I'LL ASK — always have 3+. Not asking any is a red flag to them.\n1. \"What does the first 90 days look like if this goes well?\"\n2. \"What did the last person in this role find hardest?\"\n3. \"How do you prefer to communicate — and how quickly do you expect replies?\"\n4. \"What's the thing that's most likely to go wrong here?\"\n5. \"Who else would I be working with day to day?\"\n\nTECH CHECK — 10 minutes before, every time\n[ ] Audio tested (record 10 seconds, play it back)\n[ ] Light on my face, not behind me\n[ ] Plain, tidy background\n[ ] Phone silenced, family warned, dog dealt with\n[ ] Backup: hotspot on standby, their phone number saved in case it drops\n[ ] Portfolio link open in a tab, ready to paste\n\nAFTER\n[ ] Thank-you message within 4 hrs, referencing one specific thing we discussed\n[ ] Logged in the tracker\n[ ] Note what I fumbled, so I fix it before the next one</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Post-interview follow-up</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Within 4 hours. Short, references something specific, adds one small piece of value.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>Hi [name],\n\nThanks for the time today — genuinely enjoyed it.\n\nThe thing you said about [specific thing they mentioned] stuck with me. [One sentence of a useful thought about it, or a small offer.] \"You mentioned the handover from sales to onboarding is where things get dropped — I've put a rough version of the checklist I'd use for that here: [link]. Yours regardless of how this goes.\"\n\nTo confirm what we discussed: [hours], starting [date], at [rate].\n\nHappy to do a paid trial task if that'd help you decide.\n\n[Your name]</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Record yourself answering five questions on Loom: tell me about yourself, why this role, a time something went wrong, what is your rate, and what questions do you have.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: One Loom under six minutes, watched back once with three notes on what to change.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 45 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The self-introduction is under 45 seconds</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The failure story ends with what you changed, not with an apology</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You said a rate number out loud without hedging</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You asked at least two questions of your own</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You watched it back, however painful</span></label></li></ul></div>"},{"n":8,"title":"The system: volume, follow-up, and knowing when to change","outcome":"You run applications as a repeatable weekly process with a rule for when to change strategy instead of despairing.","badges":["Workflow","Tools","Rates","1 template"],"minutes":26,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Five tailored applications a day, five days a week, is 100 a month. That is enough data to make a real decision.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Follow up once, five to seven days later, and add something new: a link, a thought about their business, an updated availability. Never send \"just following up\".</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Silence after a reply is normal and is not personal. Hiring stalls for reasons that have nothing to do with you. Keep the row in your tracker and move on.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Change one variable at a time. If you change the lane, the headline and the format at once, you learn nothing from the next 30 applications.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Set a review date before you start, not when you are demoralised. Thirty days, 100 applications, then read the tracker like a stranger would.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Keep applying after you get hired. The VAs who stay stable treat client search as a permanent low-level habit, not an emergency response.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The follow-up that gets a reply</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Hi, just following up on my application. Please let me know if you need anything else. Thank you!\"</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Hi Dana, following up on the ops assistant role. Since applying I put together the Thursday invoicing checklist I mentioned, in case it is useful either way: [link].\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Still available for the 7am to 12pm Mountain window, and happy to start with a paid first week if that is easier than deciding now.\"</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The second one gives them something and reduces their risk. The first one asks them to do emotional labour for a stranger.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">The weekly application system</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Every week until you're hired. Treat it as a job with hours, not a mood.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Monday: harvest 25 posts, don't write anything</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Separate finding from writing. Filter hard — 25 you actually match beats 100 you don't.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Tue–Fri: 5 applications a day, 20 minutes each</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Four minutes reading, twelve writing, four checking. Batching this way stops it eating your whole day.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Log every single one, immediately</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Date, company, rate, what you led with. Without the log you can't diagnose anything and you'll draw conclusions from feelings.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Follow up once at day 5–7, with something new</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">One follow-up, carrying value. Then stop, permanently, and don't take it personally.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Friday: read the funnel numbers</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Applications → replies → interviews → offers. Fix the stage where the number collapses, not the stage you feel worst about.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Change ONE thing per week and measure it</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Change five and you learn nothing. Change the opener this week, the portfolio link next week. Two weeks of data per change.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>The binge-and-crash cycle: 60 applications on Sunday, nothing for nine days, then despair. Consistency beats intensity, and the log is what keeps you honest about which one you're actually doing.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Tool comparison</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Where to actually apply</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Each board is a different market with different rates, competition and client quality. Applying the same way everywhere is why the funnel numbers look bad.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width: 52rem;\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Tool</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Best for</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Learning curve</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Cost</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Verdict</th></tr></thead><tbody><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">OnlineJobs.ph</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Volume. Employers who specifically want to hire Filipino staff long-term.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free for jobseekers</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Biggest source by far, and the lowest rates. Worth it because employers here expect a long relationship. Get your ID verified — it visibly moves you up their rankings.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Upwork</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Higher rates, and escrow protection with clients you don't know.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium — the algorithm matters</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free, 10% fee on earnings</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Hard to start (no reviews = no jobs), excellent once you have 3–4 good ones. Apply to fewer, better jobs — connects are limited and that's actually a feature.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">RemoteOK / We Work Remotely</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Salaried remote roles rather than freelance gigs.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Fewer listings, much higher pay, far more competition from everywhere in the world. Worth applying to a couple a week as a long shot with a real upside.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Indeed</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Companies hiring remote staff who aren't thinking 'VA' specifically.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Underused by VAs. Search job TITLES like 'operations coordinator' rather than 'virtual assistant' — same work, better pay, less competition.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">LinkedIn</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Being found rather than applying. Inbound beats outbound.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium — needs consistency</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Slowest to pay off and the best long-term. Post once a week about your lane for six months and clients start messaging you. Almost nobody does this.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Direct outreach</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">The best clients, who never post a job at all.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Hard — low hit rate</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Highest rates and zero competition, because you're the only applicant. Send 20 genuinely useful, researched emails and expect 1–2 conversations. Worth doing weekly.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 5 columns and scrolls horizontally on small screens.</span></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">What a working application funnel looks like</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Benchmarks so you can tell whether you have a volume problem or a quality problem. Most people diagnose the wrong one and just apply harder.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width: 38rem;\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Copy-pasted, no portfolio</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">1–3% reply</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">~1 interview per 100</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Where most people are. Applying harder does not fix this.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Personalised first line only</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">8–12% reply</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">~4 interviews per 100</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">One sentence of real effort roughly quadruples the reply rate.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Personalised + portfolio link</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">15–20% reply</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">~8 interviews per 100</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The link is what turns a reply into an interview.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Personalised + portfolio + Loom</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">20–30% reply</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">~12 interviews per 100</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Very few applicants do all three. That's exactly why it works.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Sustainable pace</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">5/day</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">~100/month</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Five properly personalised beats fifty copy-pasted, and you can keep it up.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Directional benchmarks, not guarantees — reply rates vary hugely by lane, rate and season. Use them to spot which stage of YOUR funnel is broken, not as promises.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Weekly funnel review</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Fifteen minutes every Friday. This is how you improve instead of just enduring.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>WEEK OF [date]\n\nTHE NUMBERS\nApplications sent: [n]  (target: 25)\nReplies: [n] → [n]%\nInterviews: [n] → [n]% of replies\nOffers: [n]\nTime spent: [n] hrs\n\nDIAGNOSIS — find where it collapses\nReply rate under 8%?\n  → The APPLICATION is the problem, not the volume. Stop sending more.\n  → Fix: is the first sentence about THEM? Is there a number? Is there a link?\n  → Also check: am I applying to roles I actually match?\n\nReplies but no interviews (under 30% of replies)?\n  → Your PROFILE or PORTFOLIO isn't backing up the pitch.\n  → Fix: add the Loom. Check the portfolio link actually opens for a stranger — test it in a private window.\n\nInterviews but no offers (under 20%)?\n  → Interview performance, rate, or genuine mismatch.\n  → Fix: prep sheet before every one. Practise your rate out loud. Ask every rejection for one piece of feedback.\n\nOffers but all below your floor?\n  → You're fishing at the bottom of the market.\n  → Fix: apply to the top 20% of posts and accept a lower reply rate. Fewer, better.\n\nWHAT I CHANGED THIS WEEK\n[One thing only]\n\nWHAT I'M CHANGING NEXT WEEK\n[One thing only]\n\nHONEST NOTE\n[Did I actually do 25, or did I do 9 and feel bad about it all week?\nThe feeling of applying is not the same as applying. Write the true number.]</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build your weekly application routine as a calendar block, plus a follow-up rule and a written review date with a change plan.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page operating plan: daily counts, sourcing list, follow-up rule, review date, and the one variable you will change if it fails.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 40 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The daily count is written as a number and lives in a calendar</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The follow-up rule specifies days and what new information gets added</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The review date is a real date</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You pre-committed to changing exactly one variable</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You listed two sources you have never applied through before</span></label></li></ul></div>"}],"quiz":[{"q":"You have 200 applications sent, 120 profile views, and 2 replies. Where is the leak?","options":["Sourcing: you are applying to the wrong jobs","The profile and the message: people look and leave","Interviewing: you need practice","Nothing, the market is just hard"],"answer":1,"explain":"Sixty percent of clients opened your profile, so the sourcing and subject line work. Two replies out of 120 views means the profile or the message loses them. Fix that before sending another 200."},{"q":"A job post ends with \"start your reply with the word Aspen\". You have a brilliant opening line. What do you do?","options":["Use your opening line, they will notice the quality","Mention Aspen at the end so it still appears","Write Aspen first, then your opening line","Skip the post, gimmicks are a bad sign"],"answer":2,"explain":"The filter runs before the reading does. Comply exactly, then be brilliant on line two. Failing the filter means nobody ever sees the good line."},{"q":"Which opening paragraph is strongest?","options":["\"Hi! My name is Joy and I am a passionate VA with 3 years of experience.\"","\"I saw your post and I am very interested in this position.\"","\"'Things fall through the cracks' is a follow-up problem more than an admin one, and that is the part I am good at.\"","\"I believe I am the perfect fit for this role and would love the opportunity.\""],"answer":2,"explain":"It quotes them, reframes their problem with a small piece of insight, and says nothing about you that is not immediately useful."},{"q":"A client asks your rate on a first call. Best answer?","options":["\"What's your budget? I'm flexible.\"","\"For the scope in your post, around 20 hours a week, my rate is $8 an hour and I invoice biweekly.\"","\"I usually charge more but for you I can go lower.\"","\"Whatever is standard for this kind of work.\""],"answer":1,"explain":"A package tied to a scope, then silence. Bouncing the question back tells the client the price is whatever they say first, and you never recover the difference."},{"q":"You are asked to do a trial task: rebuild their entire 400-contact CRM by Friday, unpaid.","options":["Do it, the experience alone is worth it","Refuse and end the conversation","Offer a scoped alternative: 20 contacts unpaid as a sample, or the full job as a paid first week","Do half and see if they pay"],"answer":2,"explain":"A full deliverable on a deadline is a job, not a test. Countering with a small sample or a paid week keeps the opportunity alive and prices you correctly from the first day."},{"q":"Five days after applying, no reply. What is the best follow-up?","options":["\"Just following up on my application, please let me know.\"","A short note attaching the checklist you mentioned, restating your availability, and offering a paid first week","Nothing, following up looks desperate","Apply again to the same post with a different message"],"answer":1,"explain":"One follow-up that adds new information gives them a reason to reopen the thread. A bare nudge asks a busy stranger to do the emotional work of replying to you."}],"glossary":[{"term":"Cover letter","def":"On VA job boards, the short message attached to your application. It is read before your resume and often instead of it."},{"term":"Screening filter","def":"An instruction hidden in the post, like starting your reply with a word. It exists to delete most of the pile."},{"term":"Connects","def":"Upwork's paid tokens spent to submit a proposal. They make untargeted applications literally expensive."},{"term":"ID Proof","def":"OnlineJobs.ph's identity trust score. Built from verified details; many employers filter low scores out."},{"term":"Speculative or mini audit","def":"A short, unpaid, capped review of a prospect's public setup, sent with your application."},{"term":"Trial task","def":"A small paid or clearly agreed test of your work. Fair at one to three hours, exploitative at a full deliverable."},{"term":"Response rate","def":"The share of your applications that get any reply. Under 5 percent on tailored applications means something is broken."},{"term":"Ghosting","def":"Silence after contact. Usually about their hiring process stalling, occasionally about you, never worth a second follow-up."},{"term":"Pipeline","def":"Every application still theoretically alive. Kept in a tracker so you can see stages rather than feelings."},{"term":"Referral","def":"An introduction from someone who already has trust with the client. The highest-converting path in this market."},{"term":"Anchoring","def":"The first number said in a negotiation, which quietly sets the range for everything after it."},{"term":"Proof artefact","def":"A finished thing someone can open in one click. Beats every adjective you could have used instead."}]} as DeepCourse;

export default course;
